import React, { useState } from 'react';
import { MatrixInput } from './MatrixInput';
import { MatrixTextInput } from './MatrixTextInput';
import { FileUpload } from './FileUpload';
import { ResultsDisplay } from './ResultsDisplay';
import { IterationTable } from './IterationTable';
import { Alert } from '../common/Alert';
import { Loader } from '../common/Loader';
import { lab1Api } from '../../services/api';
import { SolutionResponse, FileData } from '../../types';
import toast from 'react-hot-toast';

type InputMode = 'manual' | 'text' | 'file';

export const SLAUPage: React.FC = () => {
    const [n, setN] = useState<number>(3);
    const [inputMode, setInputMode] = useState<InputMode>('manual');
    const [matrix, setMatrix] = useState<number[][]>(Array(3).fill(0).map(() => Array(3).fill(0)));
    const [vector, setVector] = useState<number[]>(Array(3).fill(0));
    const [epsilon, setEpsilon] = useState<number>(0.0001);
    const [maxIterations, setMaxIterations] = useState<number>(100);
    const [loading, setLoading] = useState<boolean>(false);
    const [result, setResult] = useState<SolutionResponse | null>(null);

    const updateData = (newMatrix: number[][], newVector: number[]) => {
        setMatrix(newMatrix);
        setVector(newVector);
        setN(newMatrix.length);
        setResult(null);
    };

    const handleSolve = async () => {
        setLoading(true);
        try {
            const response = await lab1Api.solve({
                matrix,
                vector,
                params: { epsilon, maxIterations }
            });
            setResult(response.data);
            if (response.data.status === 'success') toast.success('Готово');
        } catch (error: any) {
            toast.error('Ошибка вычислений');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container mx-auto px-4 py-8 max-w-5xl font-mono text-sm text-slate-900">
            {/* Header */}
            <div className="mb-10 border-b-2 border-slate-900 pb-2 flex justify-between items-baseline">
                <h1 className="text-lg font-bold">LAB_01: GAUSS_SEIDEL_METHOD</h1>
                <span className="text-xs text-slate-500 underline">VAR: 20 | YASAKOV.A.A</span>
            </div>

            {/* Params & Navigation */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                <div className="col-span-1 border p-3 space-y-3 bg-slate-50">
                    <div>
                        <label className="block text-[10px] font-bold mb-1 uppercase text-slate-400">Dimension (N)</label>
                        <input type="number" value={n} onChange={(e) => setN(Number(e.target.value))} className="w-full border bg-white p-1 outline-none focus:border-black" />
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold mb-1 uppercase text-slate-400">Precision (EPS)</label>
                        <input type="number" step="0.000000001" value={epsilon} onChange={(e) => setEpsilon(Number(e.target.value))} className="w-full border bg-white p-1 outline-none focus:border-black" />
                    </div>
                </div>

                <div className="col-span-3 border flex flex-col">
                    <div className="flex border-b bg-slate-50">
                        {(['manual', 'text', 'file'] as InputMode[]).map((mode) => (
                            <button
                                key={mode}
                                onClick={() => setInputMode(mode)}
                                className={`px-6 py-2 text-[10px] font-bold uppercase tracking-widest ${inputMode === mode ? 'bg-white border-r border-l first:border-l-0' : 'text-slate-400 hover:text-slate-600'}`}
                            >
                                {mode}
                            </button>
                        ))}
                    </div>
                    <div className="p-4 flex-grow bg-white overflow-auto max-h-[400px]">
                        {inputMode === 'manual' && <MatrixInput n={n} matrix={matrix} vector={vector} onChange={updateData} />}
                        {inputMode === 'text' && <MatrixTextInput n={n} matrix={matrix} vector={vector} onChange={updateData} />}
                        {inputMode === 'file' && <FileUpload onDataLoaded={(data) => updateData(data.matrix, data.vector)} />}
                    </div>
                </div>
            </div>

            <button
                onClick={handleSolve}
                disabled={loading}
                className="w-full py-3 mb-10 border-2 border-slate-900 hover:bg-slate-900 hover:text-white font-bold uppercase transition-all disabled:opacity-30"
            >
                {loading ? 'Processing...' : 'Execute calculation'}
            </button>

            {/* Results */}
            {result && (
                <div className="border-t-4 border-slate-900 pt-6 space-y-8 animate-in fade-in duration-500">
                    <div className="flex justify-between items-center">
                        <h2 className="font-bold uppercase tracking-tighter text-xl">Calculation Report</h2>
                        <span className={`text-[10px] px-2 py-1 border font-bold ${result.diagonalDominance ? 'border-green-600 text-green-600' : 'border-amber-600 text-amber-600'}`}>
                            DIAGONAL_DOMINANCE: {result.diagonalDominance ? 'TRUE' : 'FALSE'}
                        </span>
                    </div>

                    <ResultsDisplay result={result} />

                    <div className="pt-6 border-t border-slate-200">
                        <h3 className="text-[10px] font-bold uppercase text-slate-400 mb-4 tracking-widest">Iteration Log</h3>
                        <IterationTable history={result.iterationHistory} solution={result.solution} />
                    </div>
                </div>
            )}
        </div>
    );
};
